if(PHP_SAPI!=='cli')exit(1);require_once __DIR__.'/../includes/legacy_full.php';require_once __DIR__.'/legacy_finance_support.php';
function la_row(string $table,array $raw): array {return ['table'=>$table,'raw'=>$raw,'reference_only'=>in_array($table,['tbg','tb_total','tb_masuk','tb_keluar'],true),'row_key'=>hash('sha256',lf_json([$table,$raw])),'student_ordinal'=>1,'money_columns'=>array_values(array_intersect(array_keys($raw),['U_LAIN','JUMLAH1','SPP_PERBULAN','POMG','MASUK','KELUAR','SALDO','msuk','keluar','jumlh']))];}
$rows=[la_row('siswa',['NO_INDUK'=>'212200001','NAMA'=>'Siswa Uji','KELAS'=>'1A','SPP_PERBULAN'=>'530000','POMG'=>'15000']),la_row('bayar',['NO_INDUK'=>'212200001','U_LAIN'=>'0','JUMLAH1'=>'500','TGL_BYR'=>'2019-12-31'])];
$manifest=['unit'=>1,'fingerprint'=>hash('sha256','automatic-test'),'source_date'=>'2026-10-17'];$cfg=lop_source_setup($rows,$manifest,['cutoff'=>'2026-10-19 08:00:00'],1);$catalog=lful_prepared($rows,$manifest)+['components'=>array_values(lful_catalog($rows)),'manifest'=>$manifest];$cfg=array_replace_recursive($cfg,lop_bulk_patch($rows,$catalog,$cfg,1,'students')['patch']);$cfg['other_policy']='total_details';
$p=lop_prepare($rows,$cfg,1,$manifest['source_date']);lft_assert(count($p['payments'])===1&&$p['payments'][0]['total']==='500.00'&&$p['summary']['automatic_payments']===1&&$cfg['other_policy']==='total_details','Automatic source details failed or rewrote configuration');
$source=$rows;$rows[1]['raw']['U_LAIN']='700';$p=lop_prepare($rows,$cfg,1,$manifest['source_date']);lft_assert($p['payments'][0]['total']==='700.00'&&$p['summary']['automatic_payments']===0,'Inclusive total doubled');$rows[1]['raw']['U_LAIN']='100';lft_assert(!lop_prepare($rows,$cfg,1,$manifest['source_date'])['payments'],'Contradictory positive total accepted');$rows[1]['raw']['U_LAIN']='0';$rows[1]['raw']['JUMLAH1']='-1';lft_assert(!lop_prepare($rows,$cfg,1,$manifest['source_date'])['payments'],'Negative payment accepted');
$rows=$source;
foreach(['2019-12-31T23:59:59.1234567'=>true,'2020-01-01'=>false,'2023-07-13'=>false,'2025-05-05'=>false,'2019-02-30'=>false,''=>false] as $date=>$accepted){$r=la_row('transaksi_m',['NO_INDUK'=>null,'TANGGAL'=>$date,'MASUK'=>'10000']);lft_assert((lop_unowned_history($r)!==null)===$accepted,'History date boundary failed: '.$date);}
$old=la_row('transaksi_m',['NO_INDUK'=>null,'TANGGAL'=>'2011-11-04','MASUK'=>'0','KELUAR'=>null]);$blank=la_row('tbg',['tgl'=>'1999-01-01','msuk'=>null,'keluar'=>null,'jumlh'=>null]);$recent=la_row('transaksi_m',['NO_INDUK'=>null,'TANGGAL'=>'2025-05-05','MASUK'=>'10000']);$rows=array_merge($rows,[$old,$blank,$recent,la_row('tabungan',['NO_INDUK'=>null,'SALDO'=>'10000'])]);$original=$rows;
$p=lop_prepare($rows,$cfg,1,$manifest['source_date']);lft_assert(count($p['history'])===2&&$p['summary']['accepted_history']===2&&$p['history'][$blank['row_key']]['kind']==='empty_reference','Empty references/history lost');lft_assert($p['history'][$old['row_key']]['date']==='2011-11-04 00:00:00'&&$p['history'][$old['row_key']]['amounts']['KELUAR']===null,'Original date/null rewritten');
lft_assert($p['summary']['savings_total']==='0.00'&&count($p['payments'])===1&&count($p['owners'])===1&&$rows===$original,'Anonymous history added active owner/balance/cash or changed source');
lft_assert(count(array_filter($p['references'],fn($r)=>$r['kind']==='unidentified'))===2,'Recent or undated identity not preserved in separate unresolved-owner register');lft_assert($p===lop_prepare($rows,$cfg,1,$manifest['source_date']),'Repeat projection changed');
echo "PASS: automatic exact details/inclusive totals, conflicting/negative amounts, 2019/2020 boundary, invalid/missing dates, recent anonymous records, empty references, no active balance/cash and repeat determinism.\n";
